(()=>{
 const bundle=JSON.parse(document.getElementById('report-data').textContent),counts=[...new Set(bundle.checkpoints.map(row=>row.body.count))].sort((a,b)=>a-b),selected=new Set(capturedBundleChoices.counts),boxes=new Map(),panel=document.createElement('section');panel.className='report-card';panel.setAttribute('aria-label','Choose signed record counts');const title=document.createElement('h2');title.textContent='Keep every claim at chosen counts';panel.append(title);const status=document.createElement('p');status.setAttribute('role','status');const save=document.createElement('button');save.type='button';save.textContent='Download chosen signed bundle';
 const refresh=()=>{for(const[count,box]of boxes)box.checked=selected.has(count);const claims=bundle.checkpoints.filter(row=>selected.has(row.body.count));save.disabled=saveChoices.disabled=clear.disabled=!selected.size;status.textContent=selected.size+' explicit count(s), '+claims.length+' original signed claim(s), including all supplied same-count conflicts. No import or history check.';};
 for(const count of counts){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';const claims=bundle.checkpoints.filter(row=>row.body.count===count);label.append(box,document.createTextNode('Choose signed count '+count+' ('+claims.length+' claim'+(claims.length===1?'':'s')+')'));panel.append(label);boxes.set(count,box);box.addEventListener('input',()=>{if(box.checked)selected.add(count);else selected.delete(count);refresh();});}
 const saveChoices=document.createElement('button'),clear=document.createElement('button');saveChoices.type=clear.type='button';saveChoices.textContent='Download signed-count choices';clear.textContent='Clear signed-count choices';clear.addEventListener('click',()=>{selected.clear();refresh();});saveChoices.addEventListener('click',()=>{if(!selected.size)return;const value={...capturedBundleChoices,counts:[...selected]},url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='captured-signed-count-choices.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Downloaded explicit counts bound to this complete canonical bundle and checked witness key. Resume with native bundle-picker --choices FILE; every claim is authenticated again. No import, retention, history or freshness proof.';});
 save.addEventListener('click',()=>{if(!selected.size)return;const value={...bundle,checkpoints:bundle.checkpoints.filter(row=>selected.has(row.body.count))},blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});if(blob.size>8*1024*1024)return status.textContent='Bundle exceeds8 MiB. Nothing downloaded.';const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='chosen-signed-claims.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Downloaded original chosen claims in supplied order, preserving every conflicting head at each count. Container is unsigned; separately verify/import with your independent public key. No custody, ancestry or completeness proof.';});panel.append(save,saveChoices,clear,status);document.querySelector('.filters').after(panel);refresh();
})();
